                    mTxtDescription.requestFocus();              //change focus to description field
                    break;
                case R.id.create_expense_ocr_description:
                    tv.setText(text);
                    break;

            }


        } catch (Exception e) {
            Toast.makeText(this, "Problem Capturing text!", Toast.LENGTH_SHORT).show();
        }
    }

