import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import org.apache.commons.collections4.MultiValuedMap;
import org.apache.commons.collections4.multimap.ArrayListValuedHashMap;
import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVRecord;
import org.apache.solr.client.solrj.SolrQuery;
import org.slf4j.Logger;
import org.xwiki.stability.Unstable;

public class MyVocabularyExtension extends AbstractCSVAnnotationsExtension {

    @Inject
    protected Logger logger;

    @Override
    public boolean isVocabularySupported(@Nonnull final Vocabulary vocabulary) {
        return vocabulary.getIdentifier().equals("myVocabulary"); // Replace with actual vocabulary identifier
    }

    @Override
    public void indexingStarted(@Nonnull final Vocabulary vocabulary) {
        // Initialize data if not initialized
        if (this.operationsInProgress.incrementAndGet() == 1) {
            this.data = new HashMap<>();
            try (BufferedReader in = new BufferedReader(
                new InputStreamReader(
                    new URL(getAnnotationSource()).openConnection().getInputStream(), StandardCharsets.UTF_8))) {
                CSVFormat parser = setupCSVParser(vocabulary);
                for (final CSVRecord row : parser.parse(in)) {
                    processCSVRecordRow(row, vocabulary);
                }
            } catch (final IOException ex) {
                this.logger.error("Failed to load annotation source: {}", ex.getMessage());
            }
        }
    }

    @Override
    public void extendTerm(@Nonnull final VocabularyInputTerm term, final Vocabulary vocabulary) {
        // Implement the logic to extend the term with annotation data
    }

    @Override
    public void indexingEnded(@Nonnull final Vocabulary vocabulary) {
        // Stop indexing if necessary
    }

    @Override
    public void extendQuery(final SolrQuery query, final Vocabulary vocabulary) {
        // Add annotation data to queries
    }

    private void processCSVRecordRow(final CSVRecord row, final Vocabulary vocabulary) {
        // Parse and process the row data
        Map<String, String> csvData = row.toMap();
        MultiValuedMap<String, String> termData = this.data.get(row.get(ID_KEY));

        // Add annotation data to the term
        if (termData != null) {
            termData.putAll(csvData);
        }
    }
}
```

In this example, the `processCSVRecordRow` method parses the row data and adds the annotation data to the term's data map. The `extendTerm` method handles the actual extension of the term based on the annotation data. The `indexingStarted`, `indexingEnded`, and `extendQuery` methods are called in the context of the `AbstractCSVAnnotationsExtension` class.

