    private void refreshPublicRoomsList(String roomId) {
        if (mPublicRoomsListList == null || mPublicRoomsListList.size() == 0) {
            mPublicRoomsListList = new ArrayList<List<PublicRoom>>();
            mPublicRoomsList = new ExpandableListView.Builder(getActivity()).setAdapter(mPublicRoomsListList).build();
        }
        if (roomId != null && !TextUtils.isEmpty(roomId)) {
            for (PublicRoom room : mPublicRoomsListList) {
                if (room.getRoomId().equals(roomId)) {
                    return;
                }
            }
        }
        refreshPublicRoomsList();
    }

    private void refreshPublicRoomsList(MXSession session) {
        refreshPublicRoomsList();
    }

    private void refreshPublicRoomsList(MXSession session, String roomId) {
        refreshPublicRoomsList(roomId);
    }

    private void refreshPublicRoomsList(String roomId, MXSession session) {
        refreshPublicRoomsList(roomId);
    }

    private void refreshPublicRoomsList(String roomId, MXSession session, String roomId2) {
        refreshPublicRoomsList(roomId, roomId2);
    }

    private void refreshPublicRoomsList(MXSession session, MXSession session2, String roomId) {
        refreshPublicRoomsList(roomId, roomId, session2);
    }

    private void refreshPublicRoomsList(String roomId, MXSession session, MXSession session2, String roomId2) {
