	// Perform search, then start search suggestions
	private void performSearch(String query) {
		if (query.length() == 0) {
			statusText.setText(R.string.no_query);
			return;
		}
		try {
			searchSuggestionsAdaper.clear();
			searchSuggestionsAdaper.setQuery(query);
			searchSuggestionsAdaper.setQueryType(tabTypes.get(tabSelected));
			searchSuggestionsAdaper.setTabSelected(tabSelected);
			searchSuggestionsAdaper.setTabType(tabTypes.get(tabSelected));
			searchSuggestionsAdaper.setLoading(true);
			searchSuggestionsAdaper.start();
		} catch (Exception e) {
			statusText.setText(R.string.search_error);
			return;
		}
	}

	// Refresh tab layout on search results
	private void refreshTab(final int tabIndex) {
		if (tabIndex == 0) {
			searchList.setVisibility(View.GONE);
			tabLayout.setVisibility(View.GONE);
			scanButton.setVisibility(View.GONE);
			listsPager.setVisibility(View.GONE);
			return;
		}
		searchList.setVisibility(View.VISIBLE);
		tabLayout.setVisibility(View.VISIBLE);
		scanButton.setVisibility(View.VISIBLE);
		listsPager.setVisibility(View.VISIBLE);
		searchList.setAdapter(null);

