                return;
            IPooledEnumerable eable = src.Map.GetMobilesInRange(src.Location, 4);
            if (eable == null)
                return;
            foreach (Mobile m in eable)
            {
                if (m == null || m == src || m is ShadowKnight || !CanDetect(src, m))
